#[path="../../rust/crates/genewars-core/src/plant_lifecycle.rs"] mod life;
use life::*;
use std::{env,fs,io::{BufWriter,Write},path::Path};
fn u16get(b:&[u8],at:&mut usize)->u16{let n=u16::from_le_bytes(b[*at..*at+2].try_into().unwrap());*at+=2;n}
fn main(){let a:Vec<_>=env::args().collect();let p=Path::new(&a[1]);let mut out=BufWriter::new(fs::File::create(p.join("results.bin")).unwrap());
 for b in fs::read(p.join("updates.bin")).unwrap().chunks_exact(80){let v:Vec<i32>=b.chunks_exact(4).map(|b|i32::from_le_bytes(b.try_into().unwrap())).collect();let input=FirstCounterPlantInput{active_type_at_6:v[0]as u8,flags_at_15:v[1]as u8,owner_at_18:v[2]as u8,animation_at_19:v[3]as u8,frame_at_1b:v[4]as u8,growth_i16:v[5]as i16,flags_at_2e:v[6]as u8,update_counter_at_2f:v[7]as u8,retirement_countdown_at_30:v[8]as u8,retirement_parameter_at_1d:v[9]as u8,positive_growth_neighbors_u8:v[10]as u8,crowding_limit_at_1a:v[11]as u8,check_threshold_at_1b:v[12]as u8,spread_period_at_18:v[13]as u8,signed_growth_delta_i8:v[14]as i8,cell_counter_at_13:v[15]as u8,plant_count_u16:v[16]as u16,owner_count_u16:if v[17]<0{None}else{Some(v[17]as u16)},old_frame_inside_current_view:v[18]!=0,cached_frame_present:v[19]!=0};
  match plan_first_counter_plant_update(input){Err(_)=>out.write_all(&[1]).unwrap(),Ok(r)=>{out.write_all(&[0]).unwrap();let phase=match r.phase{FirstCounterPhase::Grow=>0,FirstCounterPhase::DelayedRetirement=>1,FirstCounterPhase::Retired=>2};let values=[phase,r.active_type_at_6_after as i32,r.flags_at_15_after as i32,r.owner_at_18 as i32,r.animation_at_19_after as i32,r.frame_at_1b_after as i32,r.growth_i16_after as i32,r.flags_at_2e_after as i32,r.update_counter_at_2f_after as i32,r.retirement_countdown_at_30_after as i32,r.cell_counter_at_13_after as i32,r.plant_count_u16_after as i32,r.owner_count_u16_after.map_or(-1,|v|v as i32),r.created_count as i32,r.cleanup.unlink_cell_reference as i32,r.cleanup.old_frame_dirty_virtual_requested as i32,r.cleanup.old_frame_dirty_body_runs as i32,r.cleanup.bookkeeping_724c0_requested as i32];for n in values{out.write_all(&n.to_le_bytes()).unwrap();}}}
 }
 let b=fs::read(p.join("schedules.bin")).unwrap();let mut at=0;
 while at<b.len(){let cursor=u16get(&b,&mut at);let count=u16get(&b,&mut at);let size=u16get(&b,&mut at);let states=u16get(&b,&mut at);let slots:Vec<_>=(0..size).map(|_|{let s=PlantScheduleSlot{active_type_at_6:b[at],flags_at_15:b[at+1],flags_at_2e:b[at+2]};at+=3;s}).collect();let post:Vec<_>=(0..states).map(|_|{let i=u16get(&b,&mut at)as usize;let s=PlantCallbackState{active_type_at_6:b[at],flags_at_2e:b[at+1],created_count:b[at+2]};at+=3;(i,s)}).collect();let before=slots.clone();match plan_family1_plant_schedule(cursor,count,&slots,&post){Err(_)=>out.write_all(&[1]).unwrap(),Ok(r)=>{out.write_all(&[0]).unwrap();for n in [r.cursor_after,r.eligible_slots_consumed,r.created_count,r.second_pass_pending as u16,r.callback_indices.len()as u16,r.queued_indices.len()as u16]{out.write_all(&n.to_le_bytes()).unwrap();}for i in r.callback_indices.iter().chain(r.queued_indices.iter()){out.write_all(&(*i as u16).to_le_bytes()).unwrap();}}}assert_eq!(slots,before);}
 out.flush().unwrap();}
